// Normalise the WhatsApp Cloud API payload into clean, flat fields.
const j = $json || {};
const msg = (j.messages && j.messages[0]) || {};
const contact = (j.contacts && j.contacts[0]) || {};

const phone = msg.from || (contact.wa_id) || '';
const name = (contact.profile && contact.profile.name) || 'Customer';
const message = (msg.text && msg.text.body) || msg.button?.text || '';
const tsRaw = msg.timestamp ? Number(msg.timestamp) * 1000 : Date.now();
const timestamp = new Date(tsRaw).toISOString();

// Detect 24h follow-up replies. Exact short affirmatives/negatives are treated
// as follow-up answers; everything else is a normal support message.
const norm = message.trim().toLowerCase().replace(/[!.\s]+$/g, '');
const yesSet = ['yes','y','yep','yeah','resolved','solved','it works','fixed'];
const noSet  = ['no','n','nope','not resolved','unresolved','still broken','not fixed'];

let route = 'support';
if (yesSet.includes(norm)) route = 'followup_yes';
else if (noSet.includes(norm)) route = 'followup_no';

return { phone, name, message, timestamp, normalizedText: norm, route };

// Build a compact conversation-history string for the AI Agent prompt.
const ext = $('Extract Message Data').first().json;
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && (r['Customer Message'] || r['AI Response'] || (r.fields && (r.fields['Customer Message'] || r.fields['AI Response']))));

const historyLines = rows.map(r => {
  const f = r.fields || r;
  const when = f.Timestamp || '';
  const cust = f['Customer Message'] ? ('Customer: ' + f['Customer Message']) : '';
  const bot = f['AI Response'] ? ('Agent: ' + f['AI Response']) : '';
  return [when, cust, bot].filter(Boolean).join(' | ');
});

const historyText = historyLines.length ? historyLines.reverse().join('\n') : 'No previous conversation history.';

return [{
  json: {
    name: ext.name,
    phone: ext.phone,
    message: ext.message,
    timestamp: ext.timestamp,
    historyText,
  },
}];

