// Convert every Airtable record into a searchable document
const items = $input.all();
const docs = [];

for (const item of items) {
  // Airtable may return fields at top level or nested under .fields
  const f = item.json && item.json.fields ? item.json.fields : item.json;

  const question = f.Question != null ? f.Question : '';
  const category = f.Category != null ? f.Category : '';
  const keywords = f.Keywords != null ? f.Keywords : '';
  const answer = f.Answer != null ? f.Answer : '';

  const document =
    'Title: ' + question + '\n\n' +
    'Category: ' + category + '\n\n' +
    'Keywords:\n' + keywords + '\n\n' +
    'Answer:\n' + answer;

  docs.push({
    json: {
      document,
      title: question,
      category,
    },
  });
}

return docs;

// Report how many documents were loaded into the vector store
const count = $('Build Documents').all().length;

return [
  {
    json: {
      status: 'success',
      documents_loaded: count,
      vector_store: 'company_kb',
    },
  },
];
